            setattr(target, "notizen_sonstiger_manifestverlust", ", ".join([s for s in [getattr(target, "notizen_sonstiger_manifestverlust", ""), source] if s]))
            target.save(update_fields=[field, "notizen_sonstiger_manifestverlust"])
