def populate_effect_of_RelEffect(apps, schema_editor):
    Attribut = apps.get_model("character", "Attribut")
    Effect = apps.get_model("effect", "Effect")
    RelEffect = apps.get_model("effect", "RelEffect")
    Transaction = apps.get_model("cards", "Transaction")

    with transaction.atomic():
        # get default Attr SCH, if Effect has custom implementation on Attribut
        default_attr = Attribut.objects.get(titel="SCH")

        results = []
        for rel in RelEffect.objects.select_related(
            "target_attribut__attribut", "target_fertigkeit__fertigkeit", "source_vorteil__teil", "source_nachteil__teil", "source_talent__talent",
            "source_gfsAbility__ability", "source_klasse__klasse", "source_klasseAbility__ability",
            "source_shopBegleiter__item", "source_shopMagischeAusrüstung__item", "source_shopRüstung__item", "source_shopEinbaute__item"
        ).all():

            # build filter to find Effect to RelEffect

            filter = Q(target_fieldname=rel.target_fieldname)

            if rel.target_attribut: filter &= (Q(target_attribut=rel.target_attribut.attribut) | (Q(has_custom_implementation=True) & Q(target_attribut=default_attr)))
            if rel.target_fertigkeit: filter &= Q(target_fertigkeit=rel.target_fertigkeit.fertigkeit)
            if rel.source_vorteil: filter &= Q(source_vorteil=rel.source_vorteil.teil)
            if rel.source_nachteil: filter &= Q(source_nachteil=rel.source_nachteil.teil)
            if rel.source_talent: filter &= Q(source_talent=rel.source_talent.talent)
            if rel.source_gfsAbility: filter &= Q(source_gfsAbility=rel.source_gfsAbility.ability)
            if rel.source_klasse: filter &= Q(source_klasse=rel.source_klasse.klasse)
            if rel.source_klasseAbility: filter &= Q(source_klasseAbility=rel.source_klasseAbility.ability)
            if rel.source_shopBegleiter: filter &= Q(source_shopBegleiter=rel.source_shopBegleiter.item)
            if rel.source_shopMagischeAusrüstung: filter &= Q(source_shopMagischeAusrüstung=rel.source_shopMagischeAusrüstung.item)
            if rel.source_shopRüstung: filter &= Q(source_shopRüstung=rel.source_shopRüstung.item)
            if rel.source_shopEinbaute: filter &= Q(source_shopEinbaute=rel.source_shopEinbaute.item)

            num_effects = Effect.objects.filter(filter).count()
            if num_effects != 1: raise ValueError(f"{rel} hat {num_effects} passende Effekte")
            effect = Effect.objects.filter(filter).first()
            results.append({"rel": rel, "effect": effect})

        for r in results:
            rel = r["rel"]
            effect = r["effect"]

            if rel.wertaenderung != effect.wertaenderung or rel.wertaenderung_str != effect.wertaenderung_str:
                print(rel, effect)
                deactivate(rel, Transaction)

                rel.wertaenderung = effect.wertaenderung
                rel.wertaenderung_str = effect.wertaenderung_str
                rel.save(update_fields=["wertaenderung", "wertaenderung_str"])

                activate(rel, Transaction)
            rel.effect = effect
            rel.save(update_fields=["effect"])


